 String base(){return saved("host")+"/player_api.php?username="+enc(saved("user"))+"&password="+enc(saved("pass"));}String enc(String s){return XtreamProtocol.encode(s);}

 interface Done{void run(JSONObject obj);} void request(String action,Done cb,String error){if(saved("host").isEmpty()){new AlertDialog.Builder(this).setMessage("Add a playlist first").setPositiveButton("Login",(d,w)->login()).setNegativeButton("Cancel",null).show();return;}if(action.equals("player_api.php")){fetch(base(),cb,error);return;}final int generation=screenGeneration;new Thread(()->{try{JSONObject obj=apiBlocking(action);runOnUiThread(()->{if(!isFinishing()&&!isDestroyed()&&generation==screenGeneration)cb.run(obj);});}catch(Exception e){runOnUiThread(()->{if(!isFinishing()&&!isDestroyed()&&generation==screenGeneration)new AlertDialog.Builder(this).setMessage(error+(library.activeIsM3u()?". Check the playlist link and network, or refresh it from Playlists.":". Check the server address, account and network, then retry.")).setPositiveButton("OK",null).show();});}}).start();}
 /**
  * One player_api action for the active playlist. M3U playlists are answered locally; a custom XMLTV guide
  * answers get_short_epg. Blocking: call off the UI thread.
  */
 JSONObject apiBlocking(String action) throws Exception{if(library.activeIsM3u())return library.answer(action);if(action.startsWith("get_short_epg")&&!saved("epg_url").isEmpty()){String sid=null;int lim=4;for(String part:action.split("&")){if(part.startsWith("stream_id="))sid=java.net.URLDecoder.decode(part.substring(10),"UTF-8");else if(part.startsWith("limit="))try{lim=Integer.parseInt(part.substring(6));}catch(NumberFormatException ignored){}}if(sid!=null){JSONArray e=library.shortEpg(sid,lim);if(e!=null)return new JSONObject().put("epg_listings",e);}}String text=Library.download(base()+"&action="+action,30000);return text.trim().startsWith("[")?new JSONObject().put("list",new JSONArray(text)):new JSONObject(text);}
 /** Background player_api call with no error dialog: cb gets null on failure. */
 void apiQuiet(String action,Done cb){new Thread(()->{JSONObject obj=null;try{obj=apiBlocking(action);}catch(Exception ignored){}final JSONObject result=obj;runOnUiThread(()->{if(!isFinishing()&&!isDestroyed())cb.run(result);});}).start();}
 void fetch(String url,Done cb,String error){final int generation=screenGeneration;new Thread(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(16000);try(InputStream in=c.getInputStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);String text=out.toString("UTF-8");JSONObject obj=text.trim().startsWith("[")?new JSONObject().put("list",new JSONArray(text)):new JSONObject(text);runOnUiThread(()->{if(!isFinishing()&&!isDestroyed()&&generation==screenGeneration)cb.run(obj);});}finally{c.disconnect();}}catch(Exception e){runOnUiThread(()->{if(!isFinishing()&&!isDestroyed()&&generation==screenGeneration)new AlertDialog.Builder(this).setMessage(error+". Check the server address, account and network, then retry.").setPositiveButton("OK",null).show();});}}).start();}
 /** Background request with no error dialog and no screen check: cb gets null on failure. */
 void fetchQuiet(String url,Done cb){new Thread(()->{JSONObject obj=null;try{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(30000);try(InputStream in=c.getInputStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);String text=out.toString("UTF-8");obj=text.trim().startsWith("[")?new JSONObject().put("list",new JSONArray(text)):new JSONObject(text);}finally{c.disconnect();}}catch(Exception ignored){}final JSONObject result=obj;runOnUiThread(()->{if(!isFinishing()&&!isDestroyed())cb.run(result);});}).start();}
 /** TV guide from anywhere: on Live TV it uses the open list, elsewhere it loads every visible live channel. */
 void openGuide(String focusId){if(focusId!=null||mode.equals("live")){TvGuide.open(this,focusId);return;}openGuideSource(prefs.getString(guideSourceKey(),"all"),null);}
 String guideSourceKey(){return accountPrefix()+"guide_source";}
 /** Opens the guide on "all" channels, "fav" (Favorites) or one live category id, and remembers the choice. */
 void openGuideSource(String src,String focusId){prefs.edit().putString(guideSourceKey(),src).apply();
  if(src.equals("fav")){JSONArray fav=favoriteLive();if(fav.length()==0){Toast.makeText(this,"No favorite channels yet. Showing all channels.",Toast.LENGTH_LONG).show();openGuideSource("all",focusId);return;}items=fav;category="fav";categories=new JSONArray();try{categories.put(new JSONObject().put("category_id","fav").put("category_name","★ Favorites"));}catch(JSONException ignored){}TvGuide.open(this,focusId);return;}
  request("get_live_categories",c->{JSONArray cats=c.optJSONArray("list");request("get_live_streams"+(src.equals("all")?"":"&category_id="+enc(src)),o->{JSONArray l=o.optJSONArray("list");if(l==null)l=new JSONArray();items=withoutHiddenChannels(src.equals("all")?withoutHiddenIn("live",l):l);category=src.equals("all")?"":src;categories=cats==null?new JSONArray():cats;TvGuide.open(this,focusId);},"Unable to load channels");},"Unable to load categories");}
 /** The guide's "Showing" button: Favorites, all channels, or any visible live category. */
 void chooseGuideSource(){request("get_live_categories",o->{JSONArray cats=o.optJSONArray("list");Set<String> hidden=new HashSet<>(prefs.getStringSet(hiddenKey("live"),new HashSet<>()));List<String> ids=new ArrayList<>(),names=new ArrayList<>();ids.add("fav");names.add("★  Favorites");ids.add("all");names.add("▦  All channels");for(int i=0;cats!=null&&i<cats.length();i++){JSONObject c=cats.optJSONObject(i);if(c==null||hidden.contains(c.optString("category_id")))continue;ids.add(c.optString("category_id"));names.add("›  "+c.optString("category_name","Category"));}new AlertDialog.Builder(this).setTitle("Show in the TV guide").setItems(names.toArray(new String[0]),(d,w)->openGuideSource(ids.get(w),null)).setNegativeButton("Cancel",null).show();},"Unable to load categories");}
 /** Live favorites as channel rows, sorted by name. */
 JSONArray favoriteLive(){List<JSONObject> out=new ArrayList<>();String pre=accountPrefix()+"fav_live_";for(Map.Entry<String,?> e:prefs.getAll().entrySet()){String k=e.getKey(),title=String.valueOf(e.getValue());if(!k.startsWith(pre)||title.isEmpty())continue;String id=k.substring(pre.length()),ext=saved(accountPrefix()+"ext_live_"+id);try{out.add(new JSONObject().put("stream_id",id).put("name",title).put("container_extension",ext.isEmpty()?"ts":ext));}catch(JSONException ignored){}}Collections.sort(out,(x,y)->x.optString("name").compareToIgnoreCase(y.optString("name")));JSONArray a=new JSONArray();for(JSONObject x:out)a.put(x);return a;}
 void browse(String m){mode=m;category="";shell(m.equals("live")?"LIVE TV":m.equals("vod")?"MOVIES":"SERIES");side=new LinearLayout(this);side.setOrientation(LinearLayout.VERTICAL);ScrollView categoryScroll=new ScrollView(this);categoryScroll.setFillViewport(true);categoryScroll.addView(side);body.addView(categoryScroll,new LinearLayout.LayoutParams(0,-1,1));detail=new LinearLayout(this);detail.setOrientation(LinearLayout.VERTICAL);body.addView(detail,new LinearLayout.LayoutParams(0,-1,2));button("← Home",side,()->home());button("★ Favorites",side,()->favorites());sideFixed=2;if(m.equals("live")){button("⌕ Search channels",side,()->searchLive());sideFixed=3;}request(m.equals("live")?"get_live_categories":m.equals("vod")?"get_vod_categories":"get_series_categories",o->{categories=o.optJSONArray("list");if(categories==null)categories=new JSONArray();showCategories();},"Unable to load categories");}
 void showCategories(){side.removeViews(sideFixed,Math.max(0,side.getChildCount()-sideFixed));Set<String> hidden=hiddenCategories();button("All categories",side,()->loadItems(""));int hiddenCount=0;for(int i=0;i<categories.length();i++){JSONObject c=categories.optJSONObject(i);if(c!=null&&hidden.contains(c.optString("category_id")))hiddenCount++;}button(hiddenCount==0?"◐ Hide / show categories":"◐ Hide / show categories ("+hiddenCount+" hidden)",side,()->manageCategories());for(int i=0;i<categories.length();i++){JSONObject c=categories.optJSONObject(i);if(c==null)continue;String id=c.optString("category_id"),title=c.optString("category_name","Category");if(hidden.contains(id))continue;TextView v=button("› "+title,side,()->loadItems(id));v.setOnLongClickListener(w->{new AlertDialog.Builder(this).setTitle(title).setItems(new String[]{"Hide this category","Cancel"},(d,which)->{if(which==0){Set<String> h=hiddenCategories();h.add(id);saveHiddenCategories(h);showCategories();}}).show();return true;});}String resume=resumeCategory==null?"":resumeCategory;resumeCategory=null;loadItems(resume);}
 String hiddenKey(){return hiddenKey(mode);} String hiddenKey(String section){return accountPrefix()+"hidden_categories_"+section;}
 Set<String> hiddenCategories(){return new HashSet<>(prefs.getStringSet(hiddenKey(),new HashSet<>()));}
 void saveHiddenCategories(Set<String> hidden){prefs.edit().putStringSet(hiddenKey(),new HashSet<>(hidden)).apply();}
 /** Checklist of categories: ticked = shown. "Untick all" hides everything so you can tick back the few you want. */
 void manageCategories(){List<String> ids=new ArrayList<>(),titles=new ArrayList<>();for(int i=0;i<categories.length();i++){JSONObject c=categories.optJSONObject(i);if(c==null)continue;ids.add(c.optString("category_id"));titles.add(c.optString("category_name","Category"));}if(ids.isEmpty()){new AlertDialog.Builder(this).setMessage("No categories to manage.").setPositiveButton("OK",null).show();return;}Set<String> hidden=hiddenCategories();boolean[] shown=new boolean[ids.size()];for(int i=0;i<ids.size();i++)shown[i]=!hidden.contains(ids.get(i));
  AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Ticked categories are shown").setMultiChoiceItems(titles.toArray(new String[0]),shown,(d,which,checked)->shown[which]=checked).setPositiveButton("Save",(d,w)->{Set<String> h=hiddenCategories();for(int i=0;i<ids.size();i++){if(shown[i])h.remove(ids.get(i));else h.add(ids.get(i));}saveHiddenCategories(h);showCategories();}).setNeutralButton("Untick all",null).setNegativeButton("Cancel",null).create();
  // The middle button flips every tick without closing, so you can hide all and then tick back a few before Save.
  dialog.setOnShowListener(d->{Button toggle=dialog.getButton(AlertDialog.BUTTON_NEUTRAL);Runnable label=()->{boolean any=false;for(boolean b:shown)any|=b;toggle.setText(any?"Untick all":"Tick all");};label.run();toggle.setOnClickListener(v->{boolean any=false;for(boolean b:shown)any|=b;ListView lv=dialog.getListView();for(int i=0;i<shown.length;i++){shown[i]=!any;lv.setItemChecked(i,!any);}label.run();});ListView lv=dialog.getListView();lv.setOnItemClickListener((parent,view,pos,id)->{shown[pos]=lv.isItemChecked(pos);label.run();});});
  dialog.show();}
 void loadItems(String id){final int ticket=++listGeneration;category=id;String a=mode.equals("live")?"get_live_streams":mode.equals("vod")?"get_vod_streams":"get_series";request(a+(id.isEmpty()?"":"&category_id="+enc(id)),o->{if(ticket!=listGeneration)return;items=o.optJSONArray("list");if(items==null)items=new JSONArray();if(id.isEmpty())items=withoutHidden(items);if(mode.equals("live"))items=withoutHiddenChannels(items);showItems();},"Unable to load content");}
 JSONArray withoutHiddenIn(String section,JSONArray all){Set<String> hidden=new HashSet<>(prefs.getStringSet(hiddenKey(section),new HashSet<>()));if(hidden.isEmpty())return all;JSONArray kept=new JSONArray();for(int i=0;i<all.length();i++){JSONObject item=all.optJSONObject(i);if(item!=null&&hidden.contains(item.optString("category_id")))continue;kept.put(all.opt(i));}return kept;}
 JSONArray withoutHidden(JSONArray all){Set<String> hidden=hiddenCategories();if(hidden.isEmpty())return all;JSONArray kept=new JSONArray();for(int i=0;i<all.length();i++){JSONObject item=all.optJSONObject(i);if(item!=null&&hidden.contains(item.optString("category_id")))continue;kept.put(all.opt(i));}return kept;}
 void showItems(){showItems(0);}
 void showItems(int offset){if(offset==0&&resumeStreamId!=null){String key=mode.equals("series")?"series_id":"stream_id";for(int i=100;i<items.length();i++){JSONObject it=items.optJSONObject(i);if(it!=null&&resumeStreamId.equals(it.optString(key))){offset=i/100*100;break;}}}final int from=offset;detail.removeAllViews();LinearLayout top=new LinearLayout(this);detail.addView(top,new LinearLayout.LayoutParams(-1,-2));TextView back=button("← Categories",top,()->{if(side.getChildCount()>sideFixed)side.getChildAt(sideFixed).requestFocus();});if(mode.equals("live")){TextView search=button("⌕ Search",top,()->searchLive()),tvg=button("▦ TV Guide",top,()->TvGuide.open(this));for(TextView t:new TextView[]{back,search,tvg}){t.setLayoutParams(rowLp());t.setTextSize(18);t.setGravity(Gravity.CENTER);}}ScrollView sv=new ScrollView(this);detail.addView(sv);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);sv.addView(list);int limit=Math.min(items.length(),from+100);if(from>0)button("← Previous page",list,()->showItems(Math.max(0,from-100)));for(int i=from;i<limit;i++){JSONObject item=items.optJSONObject(i);if(item==null)continue;String title=item.optString("name","Untitled");String rowId=item.optString(mode.equals("series")?"series_id":"stream_id");boolean fav=isFavorite(mode,rowId);button(fav?"★ "+title:title,list,()->select(item)).setTag(rowId);}if(limit<items.length())button("Next page →",list,()->showItems(limit));if(!focusResume(list)&&list.getChildCount()>0)list.getChildAt(0).requestFocus();}
 void select(JSONObject item){String title=item.optString("name","Untitled");String type=mode;String id=item.optString(type.equals("series")?"series_id":"stream_id");new AlertDialog.Builder(this).setTitle(title).setItems(type.equals("live")?new String[]{"Play / Open",isFavorite(type,id)?"Remove Favorite":"Add Favorite","Program guide","Hide channel"}:new String[]{"Play / Open",isFavorite(type,id)?"Remove Favorite":"Add Favorite","Close"},(d,which)->{if(which==3){toggleHiddenChannel(id);Toast.makeText(this,"Channel hidden. Unhide it from Search channels.",Toast.LENGTH_LONG).show();items=withoutHiddenChannels(items);showItems();return;}if(which==0){if(type.equals("series"))episodes(id,title);else{zapList=items;play(type,id,item.optString("container_extension",type.equals("live")?"ts":"mp4"),title);}}if(which==2&&type.equals("live"))guide(id,title);if(which==1)toggleFavorite(type,id,title,item.optString("container_extension",type.equals("live")?"ts":"mp4"));}).show();}
 boolean toggleFavorite(String type,String id,String title,String ext){String key=accountPrefix()+"fav_"+type+"_"+id;boolean remove=isFavorite(type,id);prefs.edit().putString(key,remove?"":title).putString(accountPrefix()+"ext_"+type+"_"+id,remove?"":ext).apply();return !remove;}
 void searchLive(){
  mode="search";playerReturn=null;searchHandler.removeCallbacks(searchRender);shell("SEARCH LIVE TV");
  LinearLayout column=new LinearLayout(this);column.setOrientation(LinearLayout.VERTICAL);body.addView(column,new LinearLayout.LayoutParams(-1,-1));
  LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);column.addView(bar,new LinearLayout.LayoutParams(-1,dp(70)));
  TextView back=button("← Live TV",bar,()->browse("live"));back.setTextSize(17);back.setGravity(Gravity.CENTER);LinearLayout.LayoutParams backLp=new LinearLayout.LayoutParams(dp(170),dp(56));backLp.setMargins(dp(5),dp(5),dp(10),dp(5));back.setLayoutParams(backLp);
  searchField=new EditText(this);searchField.setSingleLine(true);searchField.setHint("⌕  Type a channel name");searchField.setText(searchQuery);searchField.setTextColor(0xffF5E8CA);searchField.setHintTextColor(0xffB89F7C);searchField.setTextSize(21);searchField.setPadding(dp(18),0,dp(18),0);searchField.setBackground(bg(PANEL));
  searchField.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH|android.view.inputmethod.EditorInfo.IME_FLAG_NO_EXTRACT_UI);searchField.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);
  searchField.setOnFocusChangeListener((v,f)->searchField.setBackground(bg(f?0xff9C5B22:PANEL)));
  bar.addView(searchField,new LinearLayout.LayoutParams(0,dp(56),1));
  searchField.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){}public void afterTextChanged(android.text.Editable e){searchQuery=e.toString();searchHandler.removeCallbacks(searchRender);searchHandler.postDelayed(searchRender,250);}});
  searchField.setOnEditorActionListener((v,action,event)->{searchHandler.removeCallbacks(searchRender);renderSearch();((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(searchField.getWindowToken(),0);if(searchResults.getChildCount()>0)searchResults.getChildAt(0).requestFocus();return true;});
  searchSummary=label("",15);searchSummary.setTextColor(0xffD9BF94);searchSummary.setPadding(dp(8),0,dp(8),0);column.addView(searchSummary,new LinearLayout.LayoutParams(-1,dp(36)));
  ScrollView sv=new ScrollView(this);searchResults=new LinearLayout(this);searchResults.setOrientation(LinearLayout.VERTICAL);sv.addView(searchResults);column.addView(sv,new LinearLayout.LayoutParams(-1,0,1));
  if(liveIndex!=null&&liveIndexAccount.equals(accountPrefix())){renderSearch();if(focusResume(searchResults))return;if(!searchQuery.isEmpty()&&searchResults.getChildCount()>0)searchResults.getChildAt(0).requestFocus();else searchField.requestFocus();return;}
  searchField.requestFocus();searchSummary.setText("Loading the channel list…");
  request("get_live_streams",o->{JSONArray list=o.optJSONArray("list");liveIndex=list==null?new JSONArray():list;liveIndexAccount=accountPrefix();liveIndexNames=new String[liveIndex.length()];for(int i=0;i<liveIndex.length();i++){JSONObject it=liveIndex.optJSONObject(i);liveIndexNames[i]=it==null?"":XtreamProtocol.searchKey(it.optString("name"));}renderSearch();},"Unable to load channels");
 }
 void renderSearch(){
  if(!mode.equals("search")||searchResults==null||liveIndex==null)return;searchResults.removeAllViews();searchHits=new JSONArray();
  String q=XtreamProtocol.searchKey(searchQuery);
  if(q.isEmpty()){Set<String> hc=hiddenChannels();List<JSONObject> hiddenItems=new ArrayList<>();for(int i=0;i<liveIndex.length();i++){JSONObject it=liveIndex.optJSONObject(i);if(it!=null&&hc.contains(it.optString("stream_id")))hiddenItems.add(it);}searchSummary.setText("Search "+liveIndex.length()+" channels. Press OK on a result to play, add to Favorites (★) or hide it (⊘)."+(hiddenItems.isEmpty()?"":"  Your hidden channels are below."));for(JSONObject it:hiddenItems)searchRow(it);return;}
  Set<String> hidden=new HashSet<>(prefs.getStringSet(hiddenKey("live"),new HashSet<>()));List<Integer> starts=new ArrayList<>(),contains=new ArrayList<>();for(int i=0;i<liveIndexNames.length;i++){if(!hidden.isEmpty()){JSONObject it=liveIndex.optJSONObject(i);if(it!=null&&hidden.contains(it.optString("category_id")))continue;}int rank=XtreamProtocol.searchRank(liveIndexNames[i],q);if(rank==0)starts.add(i);else if(rank==1)contains.add(i);}
  Set<String> hc=hiddenChannels();List<Integer> hiddenHits=new ArrayList<>();starts.addAll(contains);if(!hc.isEmpty()){for(Iterator<Integer> it=starts.iterator();it.hasNext();){int i=it.next();JSONObject o=liveIndex.optJSONObject(i);if(o!=null&&hc.contains(o.optString("stream_id"))){hiddenHits.add(i);it.remove();}}starts.addAll(hiddenHits);}int limit=Math.min(starts.size(),150);
  searchSummary.setText(starts.isEmpty()?"No channels match \""+searchQuery.trim()+"\""+(hidden.isEmpty()?"":" (hidden categories are left out)"):starts.size()+(starts.size()==1?" channel":" channels")+(limit<starts.size()?" (showing the first "+limit+", keep typing to narrow it down)":"")+"  •  ★ = in Favorites"+(hiddenHits.isEmpty()?"":"  •  ⊘ = hidden"));
  for(int n=0;n<limit;n++){JSONObject item=liveIndex.optJSONObject(starts.get(n));if(item!=null)searchRow(item);}
 }
 void searchAction(JSONObject item,TextView row){
  String id=item.optString("stream_id"),title=item.optString("name","Untitled"),ext=item.optString("container_extension","ts");if(ext.isEmpty())ext="ts";final String extension=ext;
  new AlertDialog.Builder(this).setTitle(title).setItems(new String[]{"Play",isFavorite("live",id)?"Remove from Favorites":"Add to Favorites",isChannelHidden(id)?"Unhide channel":"Hide channel","Program guide"},(d,which)->{if(which==0){zapList=searchHits;play("live",id,extension,title);}else if(which==1){boolean added=toggleFavorite("live",id,title,extension);styleSearchRow(row,id,title);Toast.makeText(this,added?"Added to Favorites":"Removed from Favorites",Toast.LENGTH_SHORT).show();}else if(which==2){boolean hidden=toggleHiddenChannel(id);styleSearchRow(row,id,title);Toast.makeText(this,hidden?"Hidden from Live TV lists":"Back in Live TV lists",Toast.LENGTH_SHORT).show();}else guide(id,title);}).show();
 }
 LinearLayout.LayoutParams rowLp(){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(dp(5),dp(5),dp(5),dp(5));return lp;}
 String hiddenChannelsKey(){return accountPrefix()+"hidden_channels_live";}
 Set<String> hiddenChannels(){return new HashSet<>(prefs.getStringSet(hiddenChannelsKey(),new HashSet<>()));}
 boolean isChannelHidden(String id){return hiddenChannels().contains(id);}
 boolean toggleHiddenChannel(String id){Set<String> h=hiddenChannels();boolean hide=!h.remove(id);if(hide)h.add(id);prefs.edit().putStringSet(hiddenChannelsKey(),h).apply();return hide;}
 JSONArray withoutHiddenChannels(JSONArray all){Set<String> hidden=hiddenChannels();if(hidden.isEmpty())return all;JSONArray kept=new JSONArray();for(int i=0;i<all.length();i++){JSONObject item=all.optJSONObject(i);if(item!=null&&hidden.contains(item.optString("stream_id")))continue;kept.put(all.opt(i));}return kept;}
 void searchRow(JSONObject item){String id=item.optString("stream_id"),title=item.optString("name","Untitled");searchHits.put(item);TextView[] ref=new TextView[1];ref[0]=button("",searchResults,()->searchAction(item,ref[0]));ref[0].setTag(id);styleSearchRow(ref[0],id,title);}
 void styleSearchRow(TextView row,String id,String title){boolean hidden=isChannelHidden(id);row.setText((hidden?"⊘ ":"")+(isFavorite("live",id)?"★ ":"")+title+(hidden?"   (hidden)":""));row.setTextColor(hidden?0xffA8977A:0xffFFFFFF);}
 boolean isFavorite(String type,String id){return !saved(accountPrefix()+"fav_"+type+"_"+id).isEmpty();}
 void favorites(){mode="favorites";shell("FAVORITES");LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);ScrollView favoritesScroll=new ScrollView(this);favoritesScroll.addView(list);body.addView(favoritesScroll,new LinearLayout.LayoutParams(-1,-1));button("← Home",list,()->home());JSONArray favLive=new JSONArray();for(Map.Entry<String,?> e:prefs.getAll().entrySet()){String k=e.getKey();if(!k.startsWith(accountPrefix()+"fav_")||String.valueOf(e.getValue()).isEmpty())continue;String[] parts=k.substring(accountPrefix().length()).split("_",3);if(parts.length!=3)continue;String t=parts[1],id=parts[2],title=String.valueOf(e.getValue());String favExt=saved(accountPrefix()+"ext_"+t+"_"+id);if(t.equals("live")){try{favLive.put(new JSONObject().put("stream_id",id).put("name",title).put("container_extension",favExt.isEmpty()?"ts":favExt));}catch(JSONException ignored){}}button("★ "+title,list,()->{if(t.equals("series"))episodes(id,title);else new AlertDialog.Builder(this).setTitle(title).setItems(new String[]{"Play","Remove Favorite"},(dialog,choice)->{if(choice==0){zapList=favLive;play(t,id,saved(accountPrefix()+"ext_"+t+"_"+id).isEmpty()?(t.equals("live")?"ts":"mp4"):saved(accountPrefix()+"ext_"+t+"_"+id),title);}else{prefs.edit().remove(k).remove(accountPrefix()+"ext_"+t+"_"+id).apply();favorites();}}).show();}).setTag(id);}if(!focusResume(list)&&list.getChildCount()>1)list.getChildAt(1).requestFocus();}
 void episodes(String id,String title){playerReturn=()->episodes(id,title);mode="episodes";shell("SERIES • "+title);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);ScrollView sv=new ScrollView(this);body.addView(sv);sv.addView(list);button("← Series",list,()->browse("series"));request("get_series_info&series_id="+enc(id),o->{JSONObject seasons=o.optJSONObject("episodes");if(seasons==null)return;Iterator<String> keys=seasons.keys();while(keys.hasNext()){String season=keys.next();button("Season "+season,list,()->{JSONArray ep=seasons.optJSONArray(season);if(ep==null)return;list.removeViews(1,list.getChildCount()-1);button("← Seasons",list,()->episodes(id,title));for(int i=0;i<ep.length();i++){JSONObject e=ep.optJSONObject(i);if(e==null)continue;String eid=e.optString("id"),ext=e.optString("container_extension","mp4"),et=e.optString("title","Episode "+(i+1));button(et,list,()->play("series",eid,ext,et)).setTag(eid);}if(!focusResume(list)&&list.getChildCount()>2)list.getChildAt(2).requestFocus();});}resumeStreamId=null;if(list.getChildCount()>1)list.getChildAt(1).requestFocus();},"Unable to load episodes");}
 String epgText(String value){try{return new String(android.util.Base64.decode(value,android.util.Base64.DEFAULT),java.nio.charset.StandardCharsets.UTF_8);}catch(IllegalArgumentException ex){return value;}}
 void guide(String id,String title){request("get_short_epg&stream_id="+enc(id)+"&limit=20",o->{JSONArray entries=o.optJSONArray("epg_listings");StringBuilder text=new StringBuilder();if(entries!=null)for(int i=0;i<entries.length();i++){JSONObject e=entries.optJSONObject(i);if(e==null)continue;text.append(e.optString("start")).append(" – ").append(e.optString("end")).append("\n").append(epgText(e.optString("title"))).append("\n").append(epgText(e.optString("description"))).append("\n\n");}new AlertDialog.Builder(this).setTitle(title+" • Program guide").setMessage(text.length()==0?"No guide data available from this provider.":text.toString()).setPositiveButton("Close",null).show();},"Unable to load guide");}
 void play(String type,String id,String ext,String title){if(library.activeIsM3u()&&!library.m3uReady()){JSONArray keep=zapList;apiQuiet("get_live_categories",o->{if(o==null){Menus.alert(this,"Couldn't load this playlist. Refresh it from Playlists.");return;}zapList=keep;play(type,id,ext,title);});return;}library.recordPlay(type,id,ext,title);String previousMode=mode;Runnable returnScreen=playerReturn;String cat=category;playerReturn=previousMode.equals("episodes")||previousMode.equals("guide")?returnScreen:previousMode.equals("favorites")?()->favorites():previousMode.equals("search")?()->searchLive():previousMode.equals("recent")?()->recent():previousMode.equals("home")||previousMode.equals("setup")?()->home():()->{resumeCategory=cat;browse(previousMode);};String url=streamUrl(type,id,ext);screenGeneration++;mode="player";if(player!=null)player.release();player=new ExoPlayer.Builder(this).build();PlayerView view=new PlayerView(this);view.setPlayer(player);view.setUseController(true);setContentView(remote.playerScreen(view,type,id,ext,title,zapList));zapList=null;player.setMediaItem(MediaItem.fromUri(url));player.prepare();player.play();view.requestFocus();}
 void closePlayer(){if(player!=null){remote.onPlayerExit();player.release();player=null;}}
 @Override public void onBackPressed(){if(remote.onBack())return;if(player!=null){closePlayer();if(playerReturn!=null)playerReturn.run();else home();return;}if(mode.equals("home")||mode.equals("setup")){super.onBackPressed();return;}if(mode.equals("login")){leaveForm();return;}if(mode.equals("search")||mode.equals("guide")){browse("live");return;}home();}
